(function(){
'use strict';
const params=new URLSearchParams(location.search);let saved='zh';try{saved=localStorage.getItem('rwlab-language')||'zh'}catch{}
const lang=params.get('lang')==='en'?'en':params.get('lang')==='zh'?'zh':saved==='en'?'en':'zh';
document.documentElement.lang=lang==='en'?'en':'zh-CN';document.documentElement.dataset.language=lang;
const dictionary={};let pieces=[],observer,busy=false;
function add(values){for(const [a,b]of Object.entries(values||{}))if(typeof b==='string')dictionary[a]=b;pieces=Object.keys(dictionary).filter(x=>(x.length>=3||['入门','进阶'].includes(x))&&/[\u3400-\u9fff]/.test(x)).sort((a,b)=>b.length-a.length);}
function t(value){if(value==null)return '';const text=String(value);if(lang!=='en'||!/[\u3400-\u9fff]/.test(text))return text;const trimmed=text.trim();if(dictionary[trimmed])return text.replace(trimmed,dictionary[trimmed]);let result=text;
 const rules=[[/共 (\d+) 条 \/ 本类 (\d+) 条/g,(_,count,total)=>(count==='1'?'1 result':count+' results')+' / '+total+' entries'],[/找到 (\d+) 项/g,(_,n)=>n==='1'?'1 setting found':n+' settings found'],[/找到 (\d+) 段代码/g,(_,n)=>n==='1'?'1 code example found':n+' code examples found'],[/(\d+) 个错误/g,'$1 errors'],[/(\d+) 个提示/g,'$1 notes'],[/(\d+) 项字段/g,'$1 settings'],[/(\d+) 类模块/g,'$1 module types'],[/(\d+) 项属性/g,'$1 properties'],[/模块 (\d+)/g,'Modules $1'],[/触发对象 (\d+)/g,'Objects $1'],[/第 (\d+) 课/g,'Lesson $1'],[/阅读约 (\d+) 分钟/g,'$1 min read'],[/(\d+) 分钟/g,'$1 min'],[/^收藏：/,'Save: '],[/^取消收藏：/,'Unsave: '],[/^移除 (.+)/,'Remove $1'],[/未找到动作：(.+?)(?:（引用只填写名称后缀）)?$/g,'Action not found: $1'],[/未找到射弹：(.+)/g,'Projectile not found: $1'],[/未打包图片：(.+)；可在素材区上传。/g,'Image not included: $1. Add it under Assets.'],[/空值：(.+)/g,'Empty value: $1'],[/内存尚未声明：(.+)/g,'Variable not declared: $1'],[/缺少基础模块：(.+)/g,'Required module missing: $1'],[/重复模块：(.+)/g,'Duplicate module: $1'],[/单位核心缺少 (.+)/g,'Unit settings are missing $1'],[/自定义或未收录字段：(.+)/g,'Custom setting: $1'],[/重复字段：(.+)/g,'Duplicate setting: $1'],[/已导入 (.+?)，导出会保留原地图地块、其他图层和外部资源引用。/g,'Opened $1. Export keeps the original tiles, layers and resource links.']];for(const [re,replacement]of rules)result=result.replace(re,replacement);for(const key of pieces)if(result.includes(key))result=result.split(key).join(dictionary[key]);return result.replace(/Found 1 code examples/g,'Found 1 code example').replace(/Found 1 settings/g,'1 setting found');}
const excluded='script,style,pre,code,textarea,svg,.manual-body,[data-no-translate],.blocklyToolbox,.blocklyWidgetDiv,.blocklyDropDownDiv';
function apply(){if(busy||!document.body)return;busy=true;observer?.disconnect();const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(node.parentElement?.closest(excluded))continue;const next=lang==='en'?t(node.nodeValue):node.nodeValue.replace(/。(?=\s*$)/g,'').replace(/。/g,'，');if(next!==node.nodeValue)node.nodeValue=next;}
 for(const el of document.querySelectorAll('[placeholder],[aria-label],[title],[alt],meta[name=description],option')){if(el.closest('svg,pre,code,textarea,[data-no-translate],.blocklyWidgetDiv,.blocklyDropDownDiv'))continue;for(const attr of ['placeholder','aria-label','title','alt',...(el.tagName==='META'?['content']:[])])if(el.hasAttribute(attr)){const before=el.getAttribute(attr),after=t(before);if(after!==before)el.setAttribute(attr,after);}}
 document.title=lang==='en'?t(document.title):document.title.replace(/。/g,'');busy=false;observer?.observe(document.body,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['placeholder','aria-label','title']});document.documentElement.classList.add('language-ready');}
function localize(data){const en=window.RW_EN_REFERENCE;if(lang!=='en'||!en)return data;for(const f of data.fields||[]){const v=en.fields?.[f.section+'|'+f.key];if(v){f.description_zh=v.description||v.label;f.label_en=v.label;f.type_en=['displayText','displayDescription'].includes(f.key)?'Text':v.type;}}for(const f of data.functions||[]){const v=en.functions?.[f.names[0]];if(v){f.description_zh=v.description||v.label;f.label_en=v.label;f.return_type_en=v.returnType;for(const param of f.parameters||[])if(v.parameters?.[param.name])param.description_zh=v.parameters[param.name];}}for(const f of data.map||[]){const v=en.map?.[f.scope+'|'+f.key];if(v){f.description_zh=v.description||v.label;f.label_en=v.label;}}
 for(const [group,entries]of Object.entries(data.mini||{}))for(const entry of entries){const v=en.miniLanguages?.[group+'|'+entry.key];if(v){entry.description_zh=v.description;entry.label_en=v.label;}}for(const f of data.stats||[])if(en.stats?.[f.key])f.description_zh=typeof en.stats[f.key]==='string'?en.stats[f.key]:en.stats[f.key].label;
 if(data.schema){for(const m of data.schema.modules)if(en.modules?.[m.id])m.label=typeof en.modules[m.id]==='string'?en.modules[m.id]:en.modules[m.id].label;for(const m of data.schema.templates){const v=en.templates?.[m.id];if(v){m.label=v.label;m.note=v.note||'';}m.requirements=[];}}
 return data;}
function reference(group,raw){if(lang!=='en')return raw;const copy=JSON.parse(JSON.stringify(raw));const data=localize({[({fields:'fields',logic:'functions',map:'map',stats:'stats'})[group]||'other']:copy});if(Array.isArray(copy))for(const f of copy){if(f.type_en){f.display_type=f.type_en;f.type=f.type_en;}if(f.return_type_en)f.return_type=f.return_type_en;if(f.default_behavior_zh&&/[\u3400-\u9fff]/.test(t(f.default_behavior_zh)))f.default_behavior_zh='See the original reference for details.';if(f.note_zh&&/[\u3400-\u9fff]/.test(t(f.note_zh)))f.note_zh='See the original reference for context and limitations.';}return copy;}
function switchLanguage(next){if(!['zh','en'].includes(next)||next===lang)return;if(!window.dispatchEvent(new CustomEvent('rw-before-language-change',{cancelable:true}))){const picker=document.querySelector('#site-language');if(picker)picker.value=lang;return;}try{localStorage.setItem('rwlab-language',next)}catch{}const url=new URL(location.href);url.searchParams.set('lang',next);location.assign(url.href);}
window.RWI18n={lang,t,add,apply,localize,reference,switchLanguage};
document.addEventListener('DOMContentLoaded',()=>{add(window.RW_UI_EN);add(window.RW_EDITOR_EN);const en=window.RW_EN_REFERENCE;if(en){const originals=window.RW_LABEL_SOURCE||{};add(originals);}
 const picker=document.querySelector('#site-language');if(picker){picker.value=lang;picker.addEventListener('change',()=>switchLanguage(picker.value));}
 observer=new MutationObserver(()=>apply());apply();document.documentElement.classList.add('language-ready');});
})();
